let xpTotal=179592, xpCroq=500, budget=5000000;
let nbCroq=0, prixCroqUnit=0;
let familierRows = [];
let rowCounter = 0;
let favSet = new Set();

function fmt(n){return Math.round(n).toLocaleString('fr-FR')}
function fmtDec(n){return parseFloat(n.toFixed(2)).toLocaleString('fr-FR')}

function prixLimite(xp){
  // Prix limite = prix croquette / qté ressource = prixCroqUnit / (xpCroq / xp)
  return prixCroqUnit / (xpCroq / xp);
}
function qteNeeded(xp){
  return xpCroq / xp;
}

function recalc(){
  xpTotal = document.getElementById('xp-total') ? parseFloat(document.getElementById('xp-total').value) : 179592;
  xpCroq = document.getElementById('xp-croquette') ? parseFloat(document.getElementById('xp-croquette').value) : 500;
  budget = document.getElementById('budget') ? parseFloat(document.getElementById('budget').value) : 5000000;
  nbCroq = xpTotal / xpCroq;
  prixCroqUnit = budget / nbCroq;
  document.getElementById('nb-croq').textContent = fmtDec(nbCroq);
  document.getElementById('prix-croq').textContent = fmt(prixCroqUnit);
  filterList();
}

function switchTab(t){
    document.querySelectorAll('.tab').forEach((el,i)=>el.classList.toggle('active',['rentabilite','favoris','liste'][i]===t));
    document.getElementById('panel-rentabilite').classList.toggle('active',t==='rentabilite');
    document.getElementById('panel-favoris').classList.toggle('active',t==='favoris');
    document.getElementById('panel-liste').classList.toggle('active',t==='liste');
    document.getElementById('panel-header').classList.toggle('active',t==='liste' || t==='favoris');

    if(t==='liste')filterList();
    if(t==='favoris')renderFavoris();
}

function filterList(){
  const q=document.getElementById('search').value.toLowerCase();
  const sort=document.getElementById('filter-sort').value;
  let data=ALL.filter(r=>r.nom.toLowerCase().includes(q));
  if(sort==='xp-desc')data.sort((a,b)=>b.xp-a.xp);
  else if(sort==='xp-asc')data.sort((a,b)=>a.xp-b.xp);
  else if(sort==='prix-asc')data.sort((a,b)=>prixLimite(a.xp)-prixLimite(b.xp));
  else if(sort==='prix-desc')data.sort((a,b)=>prixLimite(b.xp)-prixLimite(a.xp));
  else data.sort((a,b)=>a.nom.localeCompare(b.nom,'fr'));
  document.getElementById('count-badge').textContent=data.length+' ressources';
  const tbody=document.getElementById('big-tbody');
  tbody.innerHTML=data.map((r,i)=>{
    const pl=prixLimite(r.xp);
    const qte=qteNeeded(r.xp);
    const isFav = favSet.has(r.nom);
    return formatResource(isFav, r.nom, r.xp, pl);
  }).join('');
}

function checkMargeRow(input, prixLim){
  const hdv=parseFloat(input.value)||0;
  const cell=input.closest('tr').querySelector('.marge-cell-big');
  if(!hdv){cell.textContent='—';return;}
  const marge=prixLim-hdv;
  const pct=(marge/prixLim*100).toFixed(1);
  if(marge>=0){
    cell.innerHTML=`<span class="badge badge-green">+${fmt(marge)} (${pct}%)</span>`;
  }else{
    cell.innerHTML=`<span class="badge badge-red">${fmt(marge)} (${pct}%)</span>`;
  }
}

/* ===== SAUVEGARDE EXTERNE ===== */
function collectState() {
  const rows = [];
  document.querySelectorAll('.familier-row').forEach(row => {
    const inputs = row.querySelectorAll('input');
    rows.push({ n: inputs[0].value, a: inputs[1].value, v: inputs[2].value });
  });
  return {
    version: 1,
    familiers: rows,
    marge: document.getElementById('marge-slider').value,
    budget: document.getElementById('budget').value,
    favs: [...favSet]
  };
}

function exportSave() {
  const state = collectState();
  const blob = new Blob([JSON.stringify(state, null, 2)], { type: 'application/json' });
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'xp_familier_sauvegarde.json';
  a.click();
  URL.revokeObjectURL(a.href);
  showSaveLabel('✓ Fichier exporté !', 'var(--green)');
}

function importSave(input) {
  const file = input.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const state = JSON.parse(e.target.result);
      if (!state.version) throw new Error('Format invalide');

      // Appliquer marge
      if (state.marge) {
        document.getElementById('marge-slider').value = state.marge;
        document.getElementById('marge-val').textContent = state.marge + '%';
      }
      // Appliquer budget
      if (state.budget) {
        document.getElementById('budget').value = state.budget;
        recalc();
      }
      // Appliquer familiers
      document.getElementById('familier-rows').innerHTML = '';
      rowCounter = 0;
      if (state.familiers && state.familiers.length > 0) {
        state.familiers.forEach(r => addFamilierRow(r.n||'', r.a||'', r.v||''));
      } else {
        addFamilierRow();
      }
      // Appliquer favoris
      favSet = new Set(state.favs || []);
      calcRent();
      filterList();
      // Sauvegarder dans l'URL aussi
      saveState();
      showSaveLabel('✓ Sauvegarde chargée !', 'var(--green)');
    } catch(err) {
      showSaveLabel('✗ Fichier invalide', 'var(--red)');
    }
    input.value = '';
  };
  reader.readAsText(file);
}

function showSaveLabel(msg, color) {
  const el = document.getElementById('save-label');
  el.textContent = msg;
  el.style.color = color;
  setTimeout(() => { el.textContent = ''; }, 3000);
}

/* ===== FAVORIS ===== */


function toggleFav(nom, btn) {
  if (favSet.has(nom)) {
    favSet.delete(nom);
    btn.textContent = '☆';
    btn.classList.remove('active');
    btn.title = 'Ajouter aux favoris';
  } else {
    favSet.add(nom);
    btn.textContent = '⭐';
    btn.classList.add('active');
    btn.title = 'Retirer des favoris';
  }
  saveFavs();
  if (document.getElementById('panel-favoris').classList.contains('active')) renderFavoris();
}

function saveFavs() {
  try {
    const state = JSON.parse(decodeURIComponent(location.hash.replace('#','') || '{}'));
    state.favs = [...favSet];
    location.hash = encodeURIComponent(JSON.stringify(state));
  } catch(e) {}
}

function loadFavs() {
  try {
    const hash = location.hash.replace('#','');
    if (hash) {
      const state = JSON.parse(decodeURIComponent(hash));
      if (state.favs) favSet = new Set(state.favs);
    }
  } catch(e) {}
}

function renderFavoris() {
  const sort = document.getElementById('fav-sort').value;
  let data = ALL.filter(r => favSet.has(r.nom));

  if (sort === 'xp-desc') data.sort((a,b) => b.xp - a.xp);
  else if (sort === 'xp-asc') data.sort((a,b) => a.xp - b.xp);
  else if (sort === 'prix-desc') data.sort((a,b) => prixLimite(b.xp) - prixLimite(a.xp));
  else if (sort === 'prix-asc') data.sort((a,b) => prixLimite(a.xp) - prixLimite(b.xp));
  else data.sort((a,b) => a.nom.localeCompare(b.nom,'fr'));

  const tbody = document.getElementById('big-tbody');
  document.getElementById('fav-count').textContent = data.length + ' favori' + (data.length > 1 ? 's' : '');

  if (data.length === 0) {
    tbody.innerHTML = '<tr><td colspan="5" class="fav-empty"><span>⭐</span>Aucun favori — ajoute des ressources depuis la liste complète !</td></tr>';
    return;
  }

  tbody.innerHTML = data.map(r => {
    const pl = prixLimite(r.xp);
    const qte = qteNeeded(r.xp);
    return formatResource(true, r.nom, r.xp, pl);
  }).join('');
}

/* ===== RENTABILITE ===== */


function addFamilierRow(nom='', achat='', vente='') {
  const id = ++rowCounter;
  familierRows.push(id);
  const container = document.getElementById('familier-rows');
  const div = document.createElement('div');
  div.className = 'familier-row';
  div.id = 'frow-' + id;
  div.innerHTML = `
    <input type="text" placeholder="ex: Kanigloups" value="${nom}" oninput="calcRent()">
    <input type="number" placeholder="Prix lvl 1" value="${achat}" oninput="calcRent()" min="0">
    <input type="number" placeholder="Prix lvl 100" value="${vente}" oninput="calcRent()" min="0">
    <div class="diff neu" id="diff-${id}">—</div>
    <span></span>
    <button class="del-btn" onclick="delFamilierRow(${id})" title="Supprimer">✕</button>`;
  container.appendChild(div);
  calcRent();
}

function delFamilierRow(id) {
  const el = document.getElementById('frow-' + id);
  if (el) el.remove();
  familierRows = familierRows.filter(r => r !== id);
  calcRent();
  saveState();
}

function updateMarge(v) {
  document.getElementById('marge-val').textContent = v + '%';
  calcRent();
}

function calcRent() {
  const rows = document.querySelectorAll('.familier-row');
  let totalAchat = 0, totalVente = 0, valid = 0;

  rows.forEach((row, i) => {
    const inputs = row.querySelectorAll('input[type=number]');
    const achat = parseFloat(inputs[0].value) || 0;
    const vente = parseFloat(inputs[1].value) || 0;
    const diffEl = row.querySelector('.diff');
    if (achat > 0 || vente > 0) {
      const diff = vente - achat;
      diffEl.textContent = (diff >= 0 ? '+' : '') + fmt(diff) + ' k';
      diffEl.className = 'diff ' + (diff > 0 ? 'pos' : diff < 0 ? 'neg' : 'neu');
      totalAchat += achat;
      totalVente += vente;
      valid++;
    } else {
      diffEl.textContent = '—';
      diffEl.className = 'diff neu';
    }
  });

  if (valid === 0) {
    ['res-gain-brut','res-marge','res-prix-ref'].forEach(id => {
      const el = document.getElementById(id); if(el) el.textContent = '—';
    });
    document.getElementById('apply-btn').disabled = true;
    document.getElementById('apply-info').textContent = '';
    window.prixRefCalc = 0;
    const badge = document.getElementById('avg-badge');
    if (badge) badge.style.display = 'none';
    return;
  }

  const marge = parseFloat(document.getElementById('marge-slider').value) / 100;
  // Moyenne par familier
  const avgAchat = totalAchat / valid;
  const avgVente = totalVente / valid;
  const gainBrut = avgVente - avgAchat;
  const margeMontant = gainBrut * marge;
  const prixRef = gainBrut - margeMontant;
  const coutTotal = avgAchat + prixRef;
  const benefice = avgVente - coutTotal;

  // Afficher badge "moyenne sur N familiers" si > 1
  const badge = document.getElementById('avg-badge');
  if (badge) {
    if (valid > 1) {
      badge.textContent = 'Moyenne sur ' + valid + ' familier' + (valid > 1 ? 's' : '');
      badge.style.display = 'inline-block';
    } else {
      badge.style.display = 'none';
    }
  }

  document.getElementById('res-gain-brut').textContent = fmt(gainBrut) + ' k';
  document.getElementById('res-marge').textContent = '−' + fmt(margeMontant) + ' k';
  document.getElementById('res-prix-ref').textContent = fmt(prixRef) + ' k';

  document.getElementById('apply-btn').disabled = prixRef <= 0;
  window.prixRefCalc = prixRef;
}

function applyPrixRef() {
  if (!window.prixRefCalc) return;
  document.getElementById('budget').value = Math.round(window.prixRefCalc);
  recalc();
  saveState();
  switchTab('zones');
  document.getElementById('apply-info').textContent = '✓ Prix max des ressources appliqué : ' + fmt(window.prixRefCalc) + ' k';
  setTimeout(() => { document.getElementById('apply-info').textContent = ''; }, 3000);
}

// Sauvegarde via URL hash (fonctionne en file://, pas besoin de serveur)
function saveState() {
  try {
    const rows = [];
    document.querySelectorAll('.familier-row').forEach(row => {
      const inputs = row.querySelectorAll('input');
      rows.push({ n: inputs[0].value, a: inputs[1].value, v: inputs[2].value });
    });
    const state = {
      r: rows,
      m: document.getElementById('marge-slider').value,
      b: document.getElementById('budget').value
    };
    location.hash = encodeURIComponent(JSON.stringify(state));
  } catch(e) {}
}

function loadState() {
  try {
    const hash = location.hash.replace('#','');
    if (hash) {
      const state = JSON.parse(decodeURIComponent(hash));
      if (state.m) {
        document.getElementById('marge-slider').value = state.m;
        document.getElementById('marge-val').textContent = state.m + '%';
      }
      if (state.b) document.getElementById('budget').value = state.b;
      if (state.r && state.r.length > 0) {
        state.r.forEach(r => addFamilierRow(r.n||'', r.a||'', r.v||''));
      } else {
        addFamilierRow();
      }
    } else {
      addFamilierRow();
    }
  } catch(e) { addFamilierRow(); }
  loadFavs();
  calcRent();
}

// Auto-save 1 seconde après la dernière frappe
let saveTimer = null;
document.addEventListener('input', function(e) {
  if (e.target.closest('#familier-rows') || e.target.id === 'marge-slider' || e.target.id === 'budget') {
    clearTimeout(saveTimer);
    saveTimer = setTimeout(saveState, 1000);
  }
});

function formatResource(isFav, resourceName, xp, priceLimit) {
    var quantity = (179592 / xp).toFixed(2);
    
    return `<tr>
                <td style="width:36px;text-align:center"><button class="fav-btn${isFav?' active':''}" onclick="toggleFav('${resourceName.replace(/'/g,"\\'")}',this)" title="${isFav?'Retirer des favoris':'Ajouter aux favoris'}">${isFav?'⭐':'☆'}</button></td>
                <td>${resourceName}</td>
                <td style="text-align:right">${xp}</td>
                <td style="text-align:right">${quantity}</td>
                <td style="text-align:right;color:var(--gold);font-weight:700">${fmt(priceLimit)}</td>
            </tr>`;
}